        emon.Port.CellsPush(f, lo);
        emon.Port.CellsPush(f, hi);
        emon.Port.CellsPush(f, emon.Port.CellsAt(f, HTn));
        emon.Port.CellsPush(f, seq);
        emon.Port.CellsPush(f, emon.Port.CellsAt(f, HT0 + 0));
        emon.Port.CellsPush(f, emon.Port.CellsAt(f, HT0 + 1));
        emon.Port.CellsPush(f, emon.Port.CellsAt(f, HT0 + 2));
        emon.Port.CellsPush(f, emon.Port.CellsAt(f, HT0 + 3));
        emon.Port.CellsPush(f, 0);
        return 1;
    }
    internal static int PfnAddVal(emon.Port.Cells f, int lo, int hi, int v) {
        // A [lo hi value] record (a CID range or a width range).
        if (lo < 0) {
            return 0;
        }
        if (hi < lo) {
            return 0;
        }
        if (emon.Port.CellsAt(f, PCount) >= CmMax) {
            PfnWarnSet(f, 4);
            return 0;
        }
        int seq = emon.Port.CellsAt(f, HSeq);
        emon.Port.CellsSet(f, HSeq, seq + 1);
        emon.Port.CellsSet(f, PCount, emon.Port.CellsAt(f, PCount) + 1);
        emon.Port.CellsPush(f, lo);
        emon.Port.CellsPush(f, hi);
        emon.Port.CellsPush(f, v);
        emon.Port.CellsPush(f, seq);
        emon.Port.CellsPush(f, 0);
        return 1;
    }
    internal static int PfnCsPut(emon.Port.Cells f, int nb, int lohi, int lolo, int hihi, int hilo) {
        // Add a codespace range of nb bytes; each bound is two 16-bit halves.
        int n = emon.Port.CellsAt(f, HNcs);
        int at = CsBase + (n * CsStride);
        if (n >= CsMax) {
            return 0;
        }
        emon.Port.CellsSet(f, at, nb);
        emon.Port.CellsSet(f, at + 1, lohi);
        emon.Port.CellsSet(f, at + 2, lolo);
        emon.Port.CellsSet(f, at + 3, hihi);
        emon.Port.CellsSet(f, at + 4, hilo);
        emon.Port.CellsSet(f, HNcs, n + 1);
        return 1;
    }
    internal static int PfnCsAdd(emon.Port.Cells f, byte[] d, int s1, int e1, int s2, int e2) {
        int nd = PfnHexNdig(d, s1, e1);
        int nd2 = PfnHexNdig(d, s2, e2);
        int nb = (nd + 1) / 2;
        int lolo = 0;
        int lohi = 0;
        int hilo = 0;
        int hihi = 0;
        int a = 0;
        if (nb < 1) {
            nb = 1;
        }
        if (nb > 4) {
            nb = 4;
        }
        a = nd - 4;
        if (a < 0) {
            a = 0;
        }
        lolo = PfnHexWin(d, s1, e1, a, nd);
        a = nd - 8;
        if (a < 0) {
            a = 0;
        }
        if (nd > 4) {
            lohi = PfnHexWin(d, s1, e1, a, nd - 4);
        }
        a = nd2 - 4;
        if (a < 0) {
            a = 0;
        }
        hilo = PfnHexWin(d, s2, e2, a, nd2);
        a = nd2 - 8;
        if (a < 0) {
            a = 0;
        }
        if (nd2 > 4) {
            hihi = PfnHexWin(d, s2, e2, a, nd2 - 4);
        }
        return PfnCsPut(f, nb, lohi, lolo, hihi, hilo);
    }
    internal static int PfnCsByte(emon.Port.Cells f, int r, int which, int k) {
        // Byte k (0 is the first) of the lower (which 0) or upper (1) bound of
        // codespace range r.
        int at = CsBase + (r * CsStride);
        int nb = emon.Port.CellsAt(f, at);
        int sh = 8 * ((nb - 1) - k);
        int half = 0;
        int s2 = sh;
        if (sh >= 16) {
            s2 = sh - 16;
            half = emon.Port.CellsAt(f, at + (1 + (which * 2)));
        } else {
            half = emon.Port.CellsAt(f, at + (2 + (which * 2)));
        }
        if (s2 == 8) {
            return (half / 256) % 256;
        }
        return half % 256;
    }
    internal static int PfnCsMatch(emon.Port.Cells f, int r, int b0, int b1, int b2, int b3) {
        // 1 when the next bytes (-1 past the end) are a code of range r.
        int nb = emon.Port.CellsAt(f, CsBase + (r * CsStride));
        int k = 0;
        int b = 0;
        while (k < nb) {
            b = b0;
            if (k == 1) {
                b = b1;
            }
            if (k == 2) {
                b = b2;
            }
            if (k == 3) {
                b = b3;
            }
            if (b < 0) {
                return 0;
            }
            if (b < PfnCsByte(f, r, 0, k)) {
                return 0;
            }
            if (b > PfnCsByte(f, r, 1, k)) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
    public static int PfnCodeLen(emon.Port.Cells f, int b0, int b1, int b2, int b3) {
        // The length in bytes of the character code that starts the bytes b0..b3
        // (-1 past the end of the string). A simple font's codes are one byte.
        // A composite font's are as its codespace ranges say; a first byte that
        // matches no range takes the length of the shortest range.
        if (emon.Port.CellsAt(f, HKind) != 2) {
            return 1;
        }
        int nr = emon.Port.CellsAt(f, HNcs);
        int clen = 1;
        int r = 0;
        int nbx = 0;
        int shortest = 4;
        if (nr == 0) {
            return 2;
        }
        while (clen <= 4) {
            r = 0;
            while (r < nr) {
                if (emon.Port.CellsAt(f, CsBase + (r * CsStride)) == clen) {
                    if (PfnCsMatch(f, r, b0, b1, b2, b3) == 1) {
                        return clen;
                    }
                }
                r += 1;
            }
            clen += 1;
        }
        // no full match: a range whose first byte fits, else the shortest
        r = 0;
        while (r < nr) {
            nbx = emon.Port.CellsAt(f, CsBase + (r * CsStride));
            if (nbx < shortest) {
                shortest = nbx;
            }
            if (b0 >= PfnCsByte(f, r, 0, 0)) {
                if (b0 <= PfnCsByte(f, r, 1, 0)) {
                    return nbx;
                }
            }
            r += 1;
        }
        return shortest;
    }
    internal static int PfnCmapTok(emon.Port.Cells f, byte[] d, int kind) {
        // One token of a CMap program. State lives in the P_ cells.
        int sec = emon.Port.CellsAt(f, PSec);
        int mode = emon.Port.CellsAt(f, PMode);
        int argc = emon.Port.CellsAt(f, PArgc);
        int id = 0;
        int lo = 0;
        int hi = 0;
        if (kind == 4) {
            id = PfnMatch(d, emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE));
            if ((id >= 1) && (id <= 12)) {
                if ((id % 2) == 1) {
                    emon.Port.CellsSet(f, PSec, id);
                    emon.Port.CellsSet(f, PArgc, 0);
                    emon.Port.CellsSet(f, PInarr, 0);
                } else {
                    emon.Port.CellsSet(f, PSec, 0);
                    emon.Port.CellsSet(f, PArgc, 0);
                    emon.Port.CellsSet(f, PInarr, 0);
                }
            }
            if (id == 13) {
                PfnWarnSet(f, 64);
            }
            if (id == 14) {
                if (emon.Port.CellsAt(f, PLastname) == 20) {
                    if (emon.Port.CellsAt(f, PLastnum) == 1) {
                        emon.Port.CellsSet(f, HWmode, 1);
                    } else {
                        emon.Port.CellsSet(f, HWmode, 0);
                    }
                }
            }
            return 0;
        }
        if (kind == 2) {
            emon.Port.CellsSet(f, PLastname, PfnMatch(d, emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE)));
            // a glyph name as a bfchar destination is taken and ignored
            if ((sec == 3) && (argc == 1)) {
                emon.Port.CellsSet(f, PArgc, 0);
            }
            return 0;
        }
        if (kind == 3) {
            emon.Port.CellsSet(f, PLastnum, emon.Port.CellsAt(f, PNum));
        }
        // codespace ranges: two hex strings
        if (sec == 1) {
            if (kind == 1) {
                if (argc == 0) {
                    emon.Port.CellsSet(f, PA1s, emon.Port.CellsAt(f, PS));
                    emon.Port.CellsSet(f, PA1e, emon.Port.CellsAt(f, PE));
                    emon.Port.CellsSet(f, PArgc, 1);
                } else {
                    if (emon.Port.CellsAt(f, PCsok) == 1) {
                        PfnCsAdd(f, d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e), emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE));
                    }
                    emon.Port.CellsSet(f, PArgc, 0);
                }
            }
            return 0;
        }
        // bfchar: source, then a hex destination (or a name, skipped)
        if (sec == 3) {
            if (kind == 1) {
                if (argc == 0) {
                    emon.Port.CellsSet(f, PA1s, emon.Port.CellsAt(f, PS));
                    emon.Port.CellsSet(f, PA1e, emon.Port.CellsAt(f, PE));
                    emon.Port.CellsSet(f, PArgc, 1);
                } else {
                    if (mode == 1) {
                        lo = PfnHexVal(d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e));
                        PfnAddTu(f, d, lo, lo, emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE));
                    }
                    emon.Port.CellsSet(f, PArgc, 0);
                }
            } else if (argc == 1) {
                emon.Port.CellsSet(f, PArgc, 0);
            }
            return 0;
        }
        // bfrange: lo hi then a hex destination or an array of them
        if (sec == 5) {
            if (emon.Port.CellsAt(f, PInarr) == 1) {
                if (kind == 1) {
                    lo = emon.Port.CellsAt(f, PLo) + emon.Port.CellsAt(f, PIdx);
                    if ((mode == 1) && (lo <= emon.Port.CellsAt(f, PHi))) {
                        PfnAddTu(f, d, lo, lo, emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE));
                    }
                    emon.Port.CellsSet(f, PIdx, emon.Port.CellsAt(f, PIdx) + 1);
                }
                if (kind == 6) {
                    emon.Port.CellsSet(f, PInarr, 0);
                    emon.Port.CellsSet(f, PArgc, 0);
                }
            } else {
                if (kind == 1) {
                    if (argc == 0) {
                        emon.Port.CellsSet(f, PA1s, emon.Port.CellsAt(f, PS));
                        emon.Port.CellsSet(f, PA1e, emon.Port.CellsAt(f, PE));
                        emon.Port.CellsSet(f, PArgc, 1);
                    } else if (argc == 1) {
                        emon.Port.CellsSet(f, PA2s, emon.Port.CellsAt(f, PS));
                        emon.Port.CellsSet(f, PA2e, emon.Port.CellsAt(f, PE));
                        emon.Port.CellsSet(f, PArgc, 2);
                    } else {
                        if (mode == 1) {
                            lo = PfnHexVal(d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e));
                            hi = PfnHexVal(d, emon.Port.CellsAt(f, PA2s), emon.Port.CellsAt(f, PA2e));
                            PfnAddTu(f, d, lo, hi, emon.Port.CellsAt(f, PS), emon.Port.CellsAt(f, PE));
                        }
                        emon.Port.CellsSet(f, PArgc, 0);
                    }
                } else if ((kind == 5) && (argc == 2)) {
                    emon.Port.CellsSet(f, PLo, PfnHexVal(d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e)));
                    emon.Port.CellsSet(f, PHi, PfnHexVal(d, emon.Port.CellsAt(f, PA2s), emon.Port.CellsAt(f, PA2e)));
                    emon.Port.CellsSet(f, PIdx, 0);
                    emon.Port.CellsSet(f, PInarr, 1);
                }
            }
            return 0;
        }
        // cidrange: lo hi cid
        if (sec == 7) {
            if (kind == 1) {
                if (argc == 0) {
                    emon.Port.CellsSet(f, PA1s, emon.Port.CellsAt(f, PS));
                    emon.Port.CellsSet(f, PA1e, emon.Port.CellsAt(f, PE));
                    emon.Port.CellsSet(f, PArgc, 1);
                } else if (argc == 1) {
                    emon.Port.CellsSet(f, PA2s, emon.Port.CellsAt(f, PS));
                    emon.Port.CellsSet(f, PA2e, emon.Port.CellsAt(f, PE));
                    emon.Port.CellsSet(f, PArgc, 2);
                }
            } else if ((kind == 3) && (argc == 2)) {
                if (mode == 2) {
                    lo = PfnHexVal(d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e));
                    hi = PfnHexVal(d, emon.Port.CellsAt(f, PA2s), emon.Port.CellsAt(f, PA2e));
                    PfnAddVal(f, lo, hi, emon.Port.CellsAt(f, PNum));
                }
                emon.Port.CellsSet(f, PArgc, 0);
            }
            return 0;
        }
        // cidchar: code cid
        if (sec == 9) {
            if (kind == 1) {
                emon.Port.CellsSet(f, PA1s, emon.Port.CellsAt(f, PS));
                emon.Port.CellsSet(f, PA1e, emon.Port.CellsAt(f, PE));
                emon.Port.CellsSet(f, PArgc, 1);
            } else if ((kind == 3) && (argc == 1)) {
                if (mode == 2) {
                    lo = PfnHexVal(d, emon.Port.CellsAt(f, PA1s), emon.Port.CellsAt(f, PA1e));
                    PfnAddVal(f, lo, lo, emon.Port.CellsAt(f, PNum));
                }
                emon.Port.CellsSet(f, PArgc, 0);
            }
            return 0;
        }
        return 0;
    }
    public static int PfnCmap(emon.Port.Cells f, byte[] d, int mode) {
        // Parse a CMap program (decoded stream bytes). mode 1 (ToUnicode) reads
        // bfchar/bfrange into the ToUnicode table; mode 2 (an Encoding CMap)
        // reads cidchar/cidrange into the CID table and codespace ranges into the
        // font. Either way the records are appended to `f` from where it ends,
        // sorted, and the answer is their count; the caller records where they
        // start. Codespace ranges of a ToUnicode CMap are kept only when the font
        // has none yet. /WMode is read in both.
        int start = emon.Port.CellsLen(f);
        int kind = 0;
        int stride = TuStride;
        emon.Port.CellsSet(f, PPos, 0);
        emon.Port.CellsSet(f, PSec, 0);
        emon.Port.CellsSet(f, PArgc, 0);
        emon.Port.CellsSet(f, PInarr, 0);
        emon.Port.CellsSet(f, PLastname, 0);
        emon.Port.CellsSet(f, PLastnum, 0);
        emon.Port.CellsSet(f, PCount, 0);
        emon.Port.CellsSet(f, PMode, mode);
        if (mode == 2) {
            emon.Port.CellsSet(f, PCsok, 1);
            stride = ValStride;
        } else if (emon.Port.CellsAt(f, HNcs) == 0) {
            emon.Port.CellsSet(f, PCsok, 1);
        } else {
            emon.Port.CellsSet(f, PCsok, 0);
        }
        kind = PfnTok(f, d);
        while (kind != 0) {
            PfnCmapTok(f, d, kind);
            kind = PfnTok(f, d);
        }
        PfnFinish(f, start, emon.Port.CellsAt(f, PCount), stride);
        return emon.Port.CellsAt(f, PCount);
    }
    internal static int PfnAglCmp(emon.Port.Cells ar, int nh, int s, int e, int row) {
        // Compare the name's bytes [s, e) with glyph name `row`: -1, 0, 1.
        int off = Agl.AglName[row * 5 + 0];
        int ln = Agl.AglName[row * 5 + 1];
        int lim = e - s;
        int j = 0;
        int x = 0;
        int y = 0;
        if (lim > ln) {
            lim = ln;
        }
        while (j < lim) {
            x = Pdflex.PlNameByte(ar, nh, s + j);
            y = Agl.AglPool[off + j];
            if (x < y) {
                return -1;
            }
            if (x > y) {
                return 1;
            }
            j += 1;
        }
        if ((e - s) < ln) {
            return -1;
        }
        if ((e - s) > ln) {
            return 1;
        }
        return 0;
    }
    internal static int PfnAglFind(emon.Port.Cells ar, int nh, int s, int e) {
        // The glyph id (row of the AGL table) of the name's bytes [s, e), or -1.
        int lo = 0;
        int hi = 4482 - 1;
        int mid = 0;
        int c = 0;
        while (lo <= hi) {
            mid = lo + ((hi - lo) / 2);
            c = PfnAglCmp(ar, nh, s, e, mid);
            if (c == 0) {
                return mid;
            }
            if (c < 0) {
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return -1;
    }
    internal static int PfnNameGid(emon.Port.Cells ar, int nh) {
        // The glyph id of a name object, or -1: the whole name, else the part
        // before the first `.`.
        int n = Pdflex.PlNameLen(ar, nh);
        int g = 0;
        int dot = 0;
        g = PfnAglFind(ar, nh, 0, n);
        if (g >= 0) {
            return g;
        }
        while ((dot < n) && (Pdflex.PlNameByte(ar, nh, dot) != 46)) {
            dot += 1;
        }
        if ((dot > 0) && (dot < n)) {
            return PfnAglFind(ar, nh, 0, dot);
        }
        return -1;
    }
    internal static int PfnAllHex(emon.Port.Cells ar, int nh, int s, int e) {
        int k = s;
        while (k < e) {
            if (PfnHexv(Pdflex.PlNameByte(ar, nh, k)) < 0) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
    internal static int PfnNameHex(emon.Port.Cells ar, int nh, int s, int e) {
        int k = s;
        int v = 0;
        while (k < e) {
            v = (v * 16) + PfnHexv(Pdflex.PlNameByte(ar, nh, k));
            k += 1;
        }
        return v;
    }
    internal static int PfnGidCps(emon.Port.Cells f, int gid) {
        // Put glyph `gid`'s code points (AGL) in the answer registers.
        int cnt = Agl.AglName[gid * 5 + 3];
        int off = Agl.AglName[gid * 5 + 2];
        int i = 0;
        emon.Port.CellsSet(f, HTn, 0);
        while (i < cnt) {
            PfnTmpAdd(f, Agl.AglUni[off + i]);
            i += 1;
        }
        return cnt;
    }
    internal static int PfnComponent(emon.Port.Cells f, emon.Port.Cells ar, int nh, int s, int e, int zapf) {
        // One `_`-separated component of a glyph name, appended to the answer:
        // an AGL name, `uniXXXX...` or `uXXXX`..`uXXXXXX`. The names a1..a206 are
        // ZapfDingbats' own (zapf 1); in any other font they are nothing.
        int ln = e - s;
        int g = PfnAglFind(ar, nh, s, e);
        int i = 0;
        int v = 0;
        int c0 = 0;
        int c1 = 0;
        int c2 = 0;
        if (ln <= 0) {
            return 0;
        }
        if ((g >= 0) && ((Agl.AglName[g * 5 + 4] == 1) && (zapf == 0))) {
            return 0;
        }
        if (g >= 0) {
            i = 0;
            while (i < Agl.AglName[g * 5 + 3]) {
                PfnTmpAdd(f, Agl.AglUni[Agl.AglName[g * 5 + 2] + i]);
                i += 1;
            }
            return 1;
        }
        c0 = Pdflex.PlNameByte(ar, nh, s);
        if (ln >= 7) {
            c1 = Pdflex.PlNameByte(ar, nh, s + 1);
            c2 = Pdflex.PlNameByte(ar, nh, s + 2);
            if ((c0 == 117) && ((c1 == 110) && (c2 == 105))) {
                if (((ln - 3) % 4) == 0) {
                    if (PfnAllHex(ar, nh, s + 3, e) == 1) {
                        i = s + 3;
                        while (i < e) {
                            v = PfnNameHex(ar, nh, i, i + 4);
                            if ((v < 55296) || (v > 57343)) {
                                PfnTmpAdd(f, v);
                            }
                            i += 4;
                        }
                        return 1;
                    }
                }
            }
        }
        if ((c0 == 117) && ((ln >= 5) && (ln <= 7))) {
            if (PfnAllHex(ar, nh, s + 1, e) == 1) {
                v = PfnNameHex(ar, nh, s + 1, e);
                if ((v <= 1114111) && ((v < 55296) || (v > 57343))) {
                    PfnTmpAdd(f, v);
                }
                return 1;
            }
        }
        return 0;
    }
    internal static int PfnNameCps2(emon.Port.Cells f, emon.Port.Cells ar, int nh, int zapf) {
        // The Unicode value of a glyph NAME object by the AGL specification, into
        // the answer registers; answers the count of code points (0: none).
        int n = Pdflex.PlNameLen(ar, nh);
        int end = 0;
        int s = 0;
        int k = 0;
        emon.Port.CellsSet(f, HTn, 0);
        while ((end < n) && (Pdflex.PlNameByte(ar, nh, end) != 46)) {
            end += 1;
        }
        if (end == 0) {
            return 0;
        }
        s = 0;
        k = 0;
        while (k <= end) {
            if ((k == end) || (Pdflex.PlNameByte(ar, nh, k) == 95)) {
                PfnComponent(f, ar, nh, s, k, zapf);
                s = k + 1;
            }
            k += 1;
        }
        return emon.Port.CellsAt(f, HTn);
    }
    public static int PfnNameCps(emon.Port.Cells f, emon.Port.Cells ar, int nh) {
        // A glyph name's code points for a font that is not ZapfDingbats.
        return PfnNameCps2(f, ar, nh, 0);
    }
    public static int PfnNameCpsZapf(emon.Port.Cells f, emon.Port.Cells ar, int nh) {
        // ... and for ZapfDingbats, whose names a1..a206 are Unicode dingbats.
        return PfnNameCps2(f, ar, nh, 1);
    }
    internal static int PfnNormAt(emon.Port.Cells ar, int nh, int from, int want) {
        // The want-th letter or digit, lower-cased, of the name from index `from`
        // on (everything else skipped); -1 past the last.
        int n = Pdflex.PlNameLen(ar, nh);
        int k = from;
        int idx = 0;
        int c = 0;
        while (k < n) {
            c = Pdflex.PlNameByte(ar, nh, k);
            if ((c >= 65) && (c <= 90)) {
                c += 32;
            }
            if (((c >= 97) && (c <= 122)) || ((c >= 48) && (c <= 57))) {
                if (idx == want) {
                    return c;
                }
                idx += 1;
            }
            k += 1;
        }
        return -1;
    }
    internal static int PfnNormLen(emon.Port.Cells ar, int nh, int from) {
        int cnt = 0;
        while (PfnNormAt(ar, nh, from, cnt) >= 0) {
            cnt += 1;
        }
        return cnt;
    }
    internal static int PfnSubsetPrefix(emon.Port.Cells ar, int nh) {
        // 7 when the name starts with a subset tag `ABCDEF+`, else 0.
        int k = 0;
        int c = 0;
        if (Pdflex.PlNameLen(ar, nh) < 8) {
            return 0;
        }
        if (Pdflex.PlNameByte(ar, nh, 6) != 43) {
            return 0;
        }
        while (k < 6) {
            c = Pdflex.PlNameByte(ar, nh, k);
            if ((c < 65) || (c > 90)) {
                return 0;
            }
            k += 1;
        }
        return 7;
    }
    public static int PfnS14Of(emon.Port.Cells ar, int nh) {
        // Which of the fourteen standard fonts a BaseFont name means (0..13), or
        // -1. The subset tag, case, spaces, hyphens and commas do not count.
        int from = PfnSubsetPrefix(ar, nh);
        int nl = PfnNormLen(ar, nh, from);
        int lo = 0;
        int hi = 453 - 1;
        int mid = 0;
        int j = 0;
        int x = 0;
        int y = 0;
        int lim = 0;
        int cmp = 0;
        int rl = 0;
        int off = 0;
        if (nl == 0) {
            return -1;
        }
        while (lo <= hi) {
            mid = lo + ((hi - lo) / 2);
            off = Encodings.S14Alias[mid * 3 + 0];
            rl = Encodings.S14Alias[mid * 3 + 1];
            lim = nl;
            if (lim > rl) {
                lim = rl;
            }
            cmp = 0;
            j = 0;
            while ((cmp == 0) && (j < lim)) {
                x = PfnNormAt(ar, nh, from, j);
                y = Encodings.S14AliasPool[off + j];
                if (x < y) {
                    cmp = -1;
                }
                if (x > y) {
                    cmp = 1;
                }
                j += 1;
            }
            if (cmp == 0) {
                if (nl < rl) {
                    cmp = -1;
                }
                if (nl > rl) {
                    cmp = 1;
                }
            }
            if (cmp == 0) {
                return Encodings.S14Alias[mid * 3 + 2];
            }
            if (cmp < 0) {
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return -1;
    }
    internal static int PfnS14Width(int font, int gid) {
        // The AFM width of a glyph in a standard font, in hundredths of a unit, or -1.
        int key = (font * 8192) + gid;
        int lo = 0;
        int hi = 4172 - 1;
        int mid = 0;
        int kv = 0;
        if (gid < 0) {
            return -1;
        }
        while (lo <= hi) {
            mid = lo + ((hi - lo) / 2);
            kv = Encodings.S14Width[mid * 2 + 0];
            if (kv == key) {
                return Encodings.S14Width[mid * 2 + 1] * 100;
            }
            if (key < kv) {
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return -1;
    }
    internal static int PfnEntryClear(emon.Port.Cells f, int code) {
        int at = SimpleBase + (code * Entry);
        emon.Port.CellsSet(f, at, 0);
        emon.Port.CellsSet(f, at + 1, 0);
        emon.Port.CellsSet(f, at + 2, 0);
        emon.Port.CellsSet(f, at + 3, 0);
        emon.Port.CellsSet(f, at + 4, 5);
        emon.Port.CellsSet(f, at + 5, -2);
        emon.Port.CellsSet(f, at + 6, -1);
        emon.Port.CellsSet(f, at + 7, 0);
        return 0;
    }
    internal static int PfnEntryPut(emon.Port.Cells f, int code, int how) {
        // Store the answer registers as code's Unicode value, obtained `how`.
        int at = SimpleBase + (code * Entry);
        emon.Port.CellsSet(f, at, emon.Port.CellsAt(f, HTn));
        emon.Port.CellsSet(f, at + 1, emon.Port.CellsAt(f, HT0 + 0));
        emon.Port.CellsSet(f, at + 2, emon.Port.CellsAt(f, HT0 + 1));
        emon.Port.CellsSet(f, at + 3, emon.Port.CellsAt(f, HT0 + 2));
        emon.Port.CellsSet(f, at + 7, emon.Port.CellsAt(f, HT0 + 3));
        emon.Port.CellsSet(f, at + 4, how);
        return 0;
    }
    internal static int PfnEncOfName(emon.Port.Cells ar, int h) {
        // 0 Standard, 1 WinAnsi, 2 MacRoman, -2 MacExpert, -1 any other name.
        if (Pdflex.PlKindOf(ar, h) != 4) {
            return -1;
        }
        if (Pdflex.PlNameIs(ar, h, Pdfnames.PnStandardEncoding()) == 1) {
            return 0;
        }
        if (Pdflex.PlNameIs(ar, h, Pdfnames.PnWinAnsiEncoding()) == 1) {
            return 1;
        }
        if (Pdflex.PlNameIs(ar, h, Pdfnames.PnMacRomanEncoding()) == 1) {
            return 2;
        }
        if (Pdflex.PlNameIs(ar, h, Pdfnames.PnMacExpertEncoding()) == 1) {
            return -2;
        }
        return -1;
    }
    internal static int PfnIsnum(emon.Port.Cells ar, int h) {
        if (h == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, h) == 2) {
            return 1;
        }
        if (Pdflex.PlKindOf(ar, h) == 3) {
            return 1;
        }
        return 0;
    }
    internal static int PfnMicro(emon.Port.Cells ar, int h) {
        // A number times a million, saturating, for a FontMatrix entry. A real's
        // digit count is the cell `pl-ref-gen` reads (pdflex's record layout).
        int kind = Pdflex.PlKindOf(ar, h);
        int m = Pdflex.PlIntValue(ar, h);
        int sc = Pdflex.PlRefGen(ar, h);
        int neg = 0;
        if (kind == 2) {
            if (m > 2000) {
                return 2000000000;
            }
            if (m < -2000) {
                return -2000000000;
            }
            return m * 1000000;
        }
        if (kind != 3) {
            return 0;
        }
        if (m < 0) {
            neg = 1;
            m = 0 - m;
        }
        while (sc > 6) {
            m = (m + 5) / 10;
            sc -= 1;
        }
        while (sc < 6) {
            if (m > 2000) {
                m = 2000;
            }
            m *= 10;
            sc += 1;
        }
        if (neg == 1) {
            return 0 - m;
        }
        return m;
    }
    internal static int PfnRound100(int cu) {
        // Hundredths to units, half away from zero.
        if (cu < 0) {
            return 0 - (((0 - cu) + 50) / 100);
        }
        return (cu + 50) / 100;
    }
    internal static int PfnDescriptor(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, int fd) {
        // Flags, MissingWidth, Ascent and Descent (FontBBox when both are 0) from
        // a FontDescriptor.
        int mw = Pdfdoc.PdDget(src, ar, dc, a, b, st, fd, Pdfnames.PnMissingWidth());
        int av = Pdfdoc.PdDget(src, ar, dc, a, b, st, fd, Pdfnames.PnAscent());
        int dv = Pdfdoc.PdDget(src, ar, dc, a, b, st, fd, Pdfnames.PnDescent());
        int bb = Pdfdoc.PdDget(src, ar, dc, a, b, st, fd, Pdfnames.PnFontBBox());
        int asc = 0;
        int dsc = 0;
        int el = 0;
        int ev = 0;
        emon.Port.CellsSet(f, HFlags, Pdfdoc.PdDint(src, ar, dc, a, b, st, fd, Pdfnames.PnFlags(), 0));
        if (PfnIsnum(ar, mw) == 1) {
            emon.Port.CellsSet(f, HMissing, Pdflex.PlNumCp(ar, mw));
        }
        if (PfnIsnum(ar, av) == 1) {
            asc = PfnRound100(Pdflex.PlNumCp(ar, av));
        }
        if (PfnIsnum(ar, dv) == 1) {
            dsc = PfnRound100(Pdflex.PlNumCp(ar, dv));
        }
        if ((asc == 0) && (dsc == 0)) {
            if ((bb != 0) && (Pdflex.PlKindOf(ar, bb) == 6)) {
                el = Pdflex.PlFirst(ar, bb);
                el = Pdflex.PlNext(ar, el);
                if (el != 0) {
                    ev = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                    if (PfnIsnum(ar, ev) == 1) {
                        dsc = PfnRound100(Pdflex.PlNumCp(ar, ev));
                    }
                    el = Pdflex.PlNext(ar, el);
                    el = Pdflex.PlNext(ar, el);
                    if (el != 0) {
                        ev = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                        if (PfnIsnum(ar, ev) == 1) {
                            asc = PfnRound100(Pdflex.PlNumCp(ar, ev));
                        }
                    }
                }
            }
        }
        if (dsc > 0) {
            dsc = 0 - dsc;
        }
        emon.Port.CellsSet(f, HAsc, asc);
        emon.Port.CellsSet(f, HDesc, dsc);
        return 0;
    }
    internal static int PfnScaleWidth(emon.Port.Cells f, int w) {
        // A Type 3 width in glyph space to hundredths of a thousandth em: times
        // the FontMatrix's a (millionths). Other fonts: unchanged.
        int am = emon.Port.CellsAt(f, HT3scale);
        int x = w;
        if (emon.Port.CellsAt(f, HSub) != 4) {
            return w;
        }
        if (x > 2000000) {
            x = 2000000;
        }
        if (x < -2000000) {
            x = -2000000;
        }
        return ((x / 1000) * am) + (((x % 1000) * am) / 1000);
    }
    internal static int PfnLoadWidths(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, int fh) {
        // /FirstChar, /LastChar and /Widths of a simple font into the table.
        int wa = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnWidths());
        int fc = Pdfdoc.PdDint(src, ar, dc, a, b, st, fh, Pdfnames.PnFirstChar(), 0);
        int code = 0;
        int k = 0;
        int w = 0;
        int v = 0;
        emon.Port.CellsSet(f, HFirst, fc);
        emon.Port.CellsSet(f, HLast, Pdfdoc.PdDint(src, ar, dc, a, b, st, fh, Pdfnames.PnLastChar(), 255));
        if ((wa == 0) || (Pdflex.PlKindOf(ar, wa) != 6)) {
            PfnWarnSet(f, 16);
            return 0;
        }
        code = fc;
        k = Pdflex.PlFirst(ar, wa);
        while ((k != 0) && (code <= 255)) {
            v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
            if ((code >= 0) && (PfnIsnum(ar, v) == 1)) {
                w = PfnScaleWidth(f, Pdflex.PlNumCp(ar, v));
                emon.Port.CellsSet(f, (SimpleBase + (code * Entry)) + 5, w);
            }
            code += 1;
            k = Pdflex.PlNext(ar, k);
        }
        return 0;
    }
    internal static int PfnWidthFallbacks(emon.Port.Cells f) {
        // Codes /Widths does not cover: the standard font's AFM width, else
        // /MissingWidth, else -1.
        int s14 = emon.Port.CellsAt(f, HS14);
        int mw = emon.Port.CellsAt(f, HMissing);
        int code = 0;
        int at = 0;
        int w = 0;
        while (code < 256) {
            at = SimpleBase + (code * Entry);
            if (emon.Port.CellsAt(f, at + 5) == -2) {
                w = -1;
                if ((s14 >= 0) && (emon.Port.CellsAt(f, HSub) != 4)) {
                    w = PfnS14Width(s14, emon.Port.CellsAt(f, at + 6));
                }
                if ((w < 0) && (mw >= 0)) {
                    w = mw;
                }
                emon.Port.CellsSet(f, at + 5, w);
            }
            code += 1;
        }
        return 0;
    }
    internal static int PfnApplyTounicode(emon.Port.Cells f, int start, int n) {
        // Override a simple font's entries with the ToUnicode table at start, n
        // records: a value that is not empty, U+0000 or U+FFFD wins.
        int code = 0;
        int rec = 0;
        int cnt = 0;
        int ok = 0;
        while (code < 256) {
            rec = PfnFind(f, start, n, TuStride, code);
            if (rec >= 0) {
                cnt = PfnTuLoad(f, rec, code);
                ok = 1;
                if (cnt == 0) {
                    ok = 0;
                }
                if ((cnt == 1) && ((emon.Port.CellsAt(f, HT0) == 0) || (emon.Port.CellsAt(f, HT0) == 65533))) {
                    ok = 0;
                }
                if (ok == 1) {
                    PfnEntryPut(f, code, 1);
                }
            }
            code += 1;
        }
        return 0;
    }
    internal static int PfnTuLoad(emon.Port.Cells f, int rec, int code) {
        // Load ToUnicode record `rec`'s destination for `code` into the answer
        // registers: a range adds the code's offset to the last code point.
        int cnt = emon.Port.CellsAt(f, rec + 2);
        int i = 0;
        emon.Port.CellsSet(f, HTn, cnt);
        while (i < 4) {
            emon.Port.CellsSet(f, HT0 + i, emon.Port.CellsAt(f, rec + (4 + i)));
            i += 1;
        }
        if (cnt > 0) {
            emon.Port.CellsSet(f, HT0 + (cnt - 1), emon.Port.CellsAt(f, HT0 + (cnt - 1)) + (code - emon.Port.CellsAt(f, rec)));
        }
        return cnt;
    }
    public static int PfnMap(emon.Port.Cells f, int code) {
        // The Unicode value of a character code: the number of code points
        // (0 when the font says nothing), which `pfn-cp` reads back, and how it
        // was obtained (`pfn-how-of`).
        int kind = emon.Port.CellsAt(f, HKind);
        int at = 0;
        int rec = 0;
        int cnt = 0;
        emon.Port.CellsSet(f, HTn, 0);
        emon.Port.CellsSet(f, HHow, 5);
        if (kind == 1) {
            if ((code < 0) || (code > 255)) {
                return 0;
            }
            at = SimpleBase + (code * Entry);
            emon.Port.CellsSet(f, HTn, emon.Port.CellsAt(f, at));
            emon.Port.CellsSet(f, HT0 + 0, emon.Port.CellsAt(f, at + 1));
            emon.Port.CellsSet(f, HT0 + 1, emon.Port.CellsAt(f, at + 2));
            emon.Port.CellsSet(f, HT0 + 2, emon.Port.CellsAt(f, at + 3));
            emon.Port.CellsSet(f, HT0 + 3, emon.Port.CellsAt(f, at + 7));
            emon.Port.CellsSet(f, HHow, emon.Port.CellsAt(f, at + 4));
            return emon.Port.CellsAt(f, at);
        }
        if (kind == 2) {
            rec = PfnFind(f, emon.Port.CellsAt(f, HTuStart), emon.Port.CellsAt(f, HTuN), TuStride, code);
            if (rec >= 0) {
                cnt = PfnTuLoad(f, rec, code);
                if (cnt > 0) {
                    emon.Port.CellsSet(f, HHow, 1);
                    return cnt;
                }
                emon.Port.CellsSet(f, HTn, 0);
            }
            if ((emon.Port.CellsAt(f, HCmap) == 4) && ((code >= 0) && (code <= 1114111))) {
                if ((code < 55296) || (code > 57343)) {
                    emon.Port.CellsSet(f, HTn, 1);
                    emon.Port.CellsSet(f, HT0 + 0, code);
                    emon.Port.CellsSet(f, HHow, 2);
                    return 1;
                }
            }
            return 0;
        }
        return 0;
    }
    public static int PfnCid(emon.Port.Cells f, int code) {
        // The CID of a code in a composite font: the code itself for Identity
        // and unsupported CMaps, else the embedded CMap's (0 when it has none).
        int rec = 0;
        if (emon.Port.CellsAt(f, HKind) != 2) {
            return code;
        }
        if (emon.Port.CellsAt(f, HCmap) == 2) {
            rec = PfnFind(f, emon.Port.CellsAt(f, HCidStart), emon.Port.CellsAt(f, HCidN), ValStride, code);
            if (rec >= 0) {
                return emon.Port.CellsAt(f, rec + 2) + (code - emon.Port.CellsAt(f, rec));
            }
            return 0;
        }
        return code;
    }
    public static int PfnWidth(emon.Port.Cells f, int code) {
        // The advance of a code in hundredths of a thousandth of an em, or -1
        // when the font says nothing (a simple font with no /Widths, no
        // /MissingWidth and no standard metrics).
        int rec = 0;
        int cid = 0;
        int w = 0;
        if (emon.Port.CellsAt(f, HKind) == 1) {
            if ((code < 0) || (code > 255)) {
                return -1;
            }
            w = emon.Port.CellsAt(f, (SimpleBase + (code * Entry)) + 5);
            if (w == -2) {
                return -1;
            }
            return w;
        }
        if (emon.Port.CellsAt(f, HKind) == 2) {
            cid = PfnCid(f, code);
            rec = PfnFind(f, emon.Port.CellsAt(f, HWStart), emon.Port.CellsAt(f, HWN), ValStride, cid);
            if (rec >= 0) {
                return emon.Port.CellsAt(f, rec + 2);
            }
            return emon.Port.CellsAt(f, HDw);
        }
        return -1;
    }
    public static int PfnGid(emon.Port.Cells f, int code) {
        // A simple font's glyph id (an `emon.agl` row) for a code, -1 when the
        // encoding gives it no name.
        if (emon.Port.CellsAt(f, HKind) != 1) {
            return -1;
        }
        if ((code < 0) || (code > 255)) {
            return -1;
        }
        return emon.Port.CellsAt(f, (SimpleBase + (code * Entry)) + 6);
    }
    internal static int PfnLoadTounicode(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, emon.Port.Cells @out, int fh) {
        // Read the font's /ToUnicode stream into a table at the end of `f`:
        // H_TU_START and H_TU_N say where. 1 when a stream was read.
        int tu = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnToUnicode());
        int tun = 0;
        int ps = 0;
        emon.Port.CellsSet(f, HTuStart, emon.Port.CellsLen(f));
        emon.Port.CellsSet(f, HTuN, 0);
        if (tu == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, tu) != 8) {
            return 0;
        }
        ps = Pdfdoc.PdStreamData(src, ar, dc, a, b, st, tu, @out);
        if (ps != 0) {
            PfnWarnSet(f, 2);
        }
        tun = PfnCmap(f, emon.Port.CellsBytes(@out), 1);
        emon.Port.CellsSet(f, HTuN, tun);
        emon.Port.CellsSet(f, HHastu, 1);
        return 1;
    }
    internal static int PfnLoadSimple(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, emon.Port.Cells @out, int fh, int sub) {
        int fd = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnFontDescriptor());
        int bf = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnBaseFont());
        int enc = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnEncoding());
        int code = 0;
        int @base = -1;
        int guess = 0;
        int diffs = 0;
        int bn = 0;
        int gid = 0;
        int flags = 0;
        int k = 0;
        int ev = 0;
        int tustart = 0;
        int tun = 0;
        int ncp = 0;
        int zapfnames = 0;
        emon.Port.CellsSet(f, HKind, 1);
        emon.Port.CellsSet(f, HSub, sub);
        if ((bf != 0) && (Pdflex.PlKindOf(ar, bf) == 4)) {
            emon.Port.CellsSet(f, HS14, PfnS14Of(ar, bf));
        }
        if (fd != 0) {
            PfnDescriptor(src, ar, dc, a, b, st, f, fd);
        }
        flags = emon.Port.CellsAt(f, HFlags);
        if (emon.Port.CellsAt(f, HS14) == 13) {
            zapfnames = 1;
        }
        if ((emon.Port.CellsAt(f, HAsc) == 0) && (emon.Port.CellsAt(f, HS14) >= 0)) {
            emon.Port.CellsSet(f, HAsc, Encodings.S14Metric[emon.Port.CellsAt(f, HS14) * 2 + 0]);
            emon.Port.CellsSet(f, HDesc, Encodings.S14Metric[emon.Port.CellsAt(f, HS14) * 2 + 1]);
        }
        // the table, empty
        code = 0;
        while (code < 256) {
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            emon.Port.CellsPush(f, 0);
            PfnEntryClear(f, code);
            code += 1;
        }
        // the base encoding
        if ((enc != 0) && (Pdflex.PlKindOf(ar, enc) == 4)) {
            @base = PfnEncOfName(ar, enc);
        }
        if ((enc != 0) && (Pdflex.PlKindOf(ar, enc) == 7)) {
            bn = Pdfdoc.PdDget(src, ar, dc, a, b, st, enc, Pdfnames.PnBaseEncoding());
            if (bn != 0) {
                @base = PfnEncOfName(ar, bn);
            }
            diffs = Pdfdoc.PdDget(src, ar, dc, a, b, st, enc, Pdfnames.PnDifferences());
        }
        if (@base == -2) {
            PfnWarnSet(f, 8);
            @base = 0;
            guess = 1;
        }
        if ((@base == -1) && ((enc != 0) && (Pdflex.PlKindOf(ar, enc) == 4))) {
            PfnWarnSet(f, 8);
            @base = 0;
            guess = 1;
        }
        if (@base == -1) {
            if (emon.Port.CellsAt(f, HS14) == 12) {
                @base = 3;
            }
            if (emon.Port.CellsAt(f, HS14) == 13) {
                @base = 4;
            }
        }
        if ((@base == -1) && (sub != 4)) {
            @base = 0;
            if ((sub == 3) && (enc == 0)) {
                @base = 1;
            }
            if ((((flags / 4) % 2) == 1) && (((flags / 32) % 2) == 0)) {
                guess = 1;
                PfnWarnSet(f, 256);
            }
        }
        emon.Port.CellsSet(f, HEnc, @base);
        if (@base >= 0) {
            code = 0;
            while (code < 256) {
                gid = Encodings.EncGid[(@base * 256) + code];
                emon.Port.CellsSet(f, (SimpleBase + (code * Entry)) + 6, gid);
                if (gid >= 0) {
                    ncp = PfnGidCps(f, gid);
                    if ((ncp > 0) && (guess == 0)) {
                        PfnEntryPut(f, code, 2);
                    } else {
                        PfnEntryPut(f, code, 5);
                    }
                }
                code += 1;
            }
        }
        // /Differences: a number sets the code, each name after it takes the next
        if ((diffs != 0) && (Pdflex.PlKindOf(ar, diffs) == 6)) {
            code = 0;
            k = Pdflex.PlFirst(ar, diffs);
            while (k != 0) {
                ev = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                if ((ev != 0) && (Pdflex.PlKindOf(ar, ev) == 2)) {
                    code = Pdflex.PlIntValue(ar, ev);
                }
                if ((ev != 0) && (Pdflex.PlKindOf(ar, ev) == 4)) {
                    if ((code >= 0) && (code <= 255)) {
                        ncp = PfnNameCps2(f, ar, ev, zapfnames);
                        emon.Port.CellsSet(f, (SimpleBase + (code * Entry)) + 6, PfnNameGid(ar, ev));
                        if (ncp > 0) {
                            PfnEntryPut(f, code, 3);
                        } else {
                            PfnEntryPut(f, code, 5);
                        }
                    }
                    code += 1;
                }
                k = Pdflex.PlNext(ar, k);
            }
        }
        // ToUnicode wins where it says something
        if (PfnLoadTounicode(src, ar, dc, a, b, st, f, @out, fh) == 1) {
            tustart = emon.Port.CellsAt(f, HTuStart);
            tun = emon.Port.CellsAt(f, HTuN);
            PfnApplyTounicode(f, tustart, tun);
            emon.Port.CellsDrop(f, tustart);
            emon.Port.CellsSet(f, HTuN, 0);
        }
        // Type 3: the FontMatrix's a scales the widths
        if (sub == 4) {
            ev = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnFontMatrix());
            if ((ev != 0) && (Pdflex.PlKindOf(ar, ev) == 6)) {
                k = Pdflex.PlFirst(ar, ev);
                ev = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                if (PfnIsnum(ar, ev) == 1) {
                    emon.Port.CellsSet(f, HT3scale, PfnMicro(ar, ev));
                }
            }
        }
        PfnLoadWidths(src, ar, dc, a, b, st, f, fh);
        PfnWidthFallbacks(f);
        return 0;
    }
    internal static int PfnParseW(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, int wa) {
        // A /W array: `c [w1 w2 ...]` and `c1 c2 w`, into the width table at the
        // end of `f`.
        int k = Pdflex.PlFirst(ar, wa);
        int k2 = 0;
        int k3 = 0;
        int v1 = 0;
        int v2 = 0;
        int v3 = 0;
        int j = 0;
        int c1 = 0;
        int el = 0;
        int ev = 0;
        emon.Port.CellsSet(f, HWStart, emon.Port.CellsLen(f));
        emon.Port.CellsSet(f, PCount, 0);
        while (k != 0) {
            v1 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
            k2 = Pdflex.PlNext(ar, k);
            if (k2 == 0) {
                k = 0;
            } else {
                c1 = Pdflex.PlIntValue(ar, v1);
                if (PfnIsnum(ar, v1) != 1) {
                    c1 = -1;
                }
                v2 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k2);
                if ((v2 != 0) && (Pdflex.PlKindOf(ar, v2) == 6)) {
                    j = 0;
                    el = Pdflex.PlFirst(ar, v2);
                    while (el != 0) {
                        ev = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                        if (PfnIsnum(ar, ev) == 1) {
                            PfnAddVal(f, c1 + j, c1 + j, Pdflex.PlNumCp(ar, ev));
                        }
                        j += 1;
                        el = Pdflex.PlNext(ar, el);
                    }
                    k = Pdflex.PlNext(ar, k2);
                } else {
                    k3 = Pdflex.PlNext(ar, k2);
                    if (k3 == 0) {
                        k = 0;
                    } else {
                        v3 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k3);
                        if ((PfnIsnum(ar, v2) == 1) && (PfnIsnum(ar, v3) == 1)) {
                            PfnAddVal(f, c1, Pdflex.PlIntValue(ar, v2), Pdflex.PlNumCp(ar, v3));
                        }
                        k = Pdflex.PlNext(ar, k3);
                    }
                }
            }
        }
        emon.Port.CellsSet(f, HWN, emon.Port.CellsAt(f, PCount));
        PfnFinish(f, emon.Port.CellsAt(f, HWStart), emon.Port.CellsAt(f, HWN), ValStride);
        return 0;
    }
    internal static int PfnNameAt(emon.Port.Cells ar, int nh, int i) {
        if (i < 0) {
            return -1;
        }
        if (i >= Pdflex.PlNameLen(ar, nh)) {
            return -1;
        }
        return Pdflex.PlNameByte(ar, nh, i);
    }
    internal static int PfnNameHas(emon.Port.Cells ar, int nh, int c0, int c1, int c2, int c3, int c4) {
        // 1 when the name contains the bytes c0 c1 c2 c3 (c4 too when it is
        // >= 0) in a row; c3 < 0 means three bytes.
        int n = Pdflex.PlNameLen(ar, nh);
        int k = 0;
        while (k < n) {
            if ((PfnNameAt(ar, nh, k) == c0) && ((PfnNameAt(ar, nh, k + 1) == c1) && (PfnNameAt(ar, nh, k + 2) == c2))) {
                if ((c3 < 0) || ((PfnNameAt(ar, nh, k + 3) == c3) && ((c4 < 0) || (PfnNameAt(ar, nh, k + 4) == c4)))) {
                    return 1;
                }
            }
            k += 1;
        }
        return 0;
    }
    internal static int PfnEncodingCmap(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, emon.Port.Cells @out, int enc) {
        // A composite font's /Encoding: a name (Identity-H/V, a predefined
        // Unicode CMap, another predefined CMap we cannot read) or an embedded
        // CMap stream.
        int ps = 0;
        int n = 0;
        int vert = 0;
        if (enc == 0) {
            emon.Port.CellsSet(f, HCmap, 1);
            PfnCsPut(f, 2, 0, 0, 0, 65535);
            return 0;
        }
        if (Pdflex.PlKindOf(ar, enc) == 8) {
            emon.Port.CellsSet(f, HCmap, 2);
            emon.Port.CellsSet(f, HCidStart, emon.Port.CellsLen(f));
            ps = Pdfdoc.PdStreamData(src, ar, dc, a, b, st, enc, @out);
            if (ps != 0) {
                PfnWarnSet(f, 512);
            }
            n = PfnCmap(f, emon.Port.CellsBytes(@out), 2);
            emon.Port.CellsSet(f, HCidN, n);
            return 0;
        }
        if (Pdflex.PlKindOf(ar, enc) != 4) {
            return 0;
        }
        emon.Port.CellsSet(f, HCmap, 1);
        if (Pdflex.PlNameIs(ar, enc, Pdfnames.PnIdentityH()) == 1) {
            PfnCsPut(f, 2, 0, 0, 0, 65535);
            return 0;
        }
        if (Pdflex.PlNameIs(ar, enc, Pdfnames.PnIdentityV()) == 1) {
            emon.Port.CellsSet(f, HWmode, 1);
            PfnCsPut(f, 2, 0, 0, 0, 65535);
            return 0;
        }
        n = Pdflex.PlNameLen(ar, enc);
        if ((n > 2) && (Pdflex.PlNameByte(ar, enc, n - 1) == 86)) {
            if (Pdflex.PlNameByte(ar, enc, n - 2) == 45) {
                vert = 1;
            }
        }
        emon.Port.CellsSet(f, HWmode, vert);
        // Uni*-UCS2-* and Uni*-UTF16-*: the code is the Unicode value
        if ((PfnNameAt(ar, enc, 0) == 85) && ((PfnNameAt(ar, enc, 1) == 110) && (PfnNameAt(ar, enc, 2) == 105))) {
            if (PfnNameHas(ar, enc, 85, 67, 83, 50, -1) == 1) {
                emon.Port.CellsSet(f, HCmap, 4);
                PfnWarnSet(f, 1);
                PfnCsPut(f, 2, 0, 0, 0, 65535);
                return 0;
            }
            if (PfnNameHas(ar, enc, 85, 84, 70, 49, 54) == 1) {
                emon.Port.CellsSet(f, HCmap, 4);
                PfnWarnSet(f, 1);
                PfnCsPut(f, 2, 0, 0, 0, 55295);
                PfnCsPut(f, 2, 0, 57344, 0, 65535);
                PfnCsPut(f, 4, 55296, 56320, 56319, 57343);
                return 0;
            }
        }
        emon.Port.CellsSet(f, HCmap, 3);
        PfnWarnSet(f, 1);
        return 0;
    }
    internal static int PfnLoadComposite(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, emon.Port.Cells @out, int fh) {
        int da = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnDescendantFonts());
        int enc = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnEncoding());
        int dd = 0;
        int fd = 0;
        int dwv = 0;
        int d2 = 0;
        int d2e = 0;
        int wa = 0;
        int d2f = 0;
        int dfirst = 0;
        int d2v = 0;
        emon.Port.CellsSet(f, HKind, 2);
        emon.Port.CellsSet(f, HSub, 5);
        if ((da != 0) && (Pdflex.PlKindOf(ar, da) == 6)) {
            dfirst = Pdflex.PlFirst(ar, da);
            dd = Pdfdoc.PdResolve(src, ar, dc, a, b, st, dfirst);
        }
        if ((dd != 0) && (Pdflex.PlKindOf(ar, dd) != 7)) {
            dd = 0;
        }
        if (dd == 0) {
            PfnWarnSet(f, 32);
        } else {
            fd = Pdfdoc.PdDget(src, ar, dc, a, b, st, dd, Pdfnames.PnFontDescriptor());
            if (fd != 0) {
                PfnDescriptor(src, ar, dc, a, b, st, f, fd);
            }
            dwv = Pdfdoc.PdDget(src, ar, dc, a, b, st, dd, Pdfnames.PnDw());
            if (PfnIsnum(ar, dwv) == 1) {
                emon.Port.CellsSet(f, HDw, Pdflex.PlNumCp(ar, dwv));
            }
            d2 = Pdfdoc.PdDget(src, ar, dc, a, b, st, dd, Pdfnames.PnDw2());
            if ((d2 != 0) && (Pdflex.PlKindOf(ar, d2) == 6)) {
                d2f = Pdflex.PlFirst(ar, d2);
                d2e = Pdfdoc.PdResolve(src, ar, dc, a, b, st, d2f);
                if (PfnIsnum(ar, d2e) == 1) {
                    emon.Port.CellsSet(f, HDw2v, Pdflex.PlNumCp(ar, d2e));
                }
                d2e = Pdflex.PlNext(ar, d2f);
                if (d2e != 0) {
                    d2v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, d2e);
                    if (PfnIsnum(ar, d2v) == 1) {
                        emon.Port.CellsSet(f, HDw2w, Pdflex.PlNumCp(ar, d2v));
                    }
                }
            }
            wa = Pdfdoc.PdDget(src, ar, dc, a, b, st, dd, Pdfnames.PnW());
        }
        PfnEncodingCmap(src, ar, dc, a, b, st, f, @out, enc);
        PfnLoadTounicode(src, ar, dc, a, b, st, f, @out, fh);
        if (emon.Port.CellsAt(f, HNcs) == 0) {
            PfnCsPut(f, 2, 0, 0, 0, 65535);
        }
        if ((wa != 0) && (Pdflex.PlKindOf(ar, wa) == 6)) {
            PfnParseW(src, ar, dc, a, b, st, f, wa);
        }
        return 0;
    }
    public static int PfnFromCmap(emon.Port.Cells f, byte[] data, int mode) {
        // A composite font made from one CMap program alone (decoded bytes): mode
        // 1 a ToUnicode CMap (codes -> Unicode), mode 2 an encoding CMap (codespace
        // and CIDs). For tools that hold a CMap and no font, and for the laws.
        int n = 0;
        PfnInit(f);
        emon.Port.CellsSet(f, HKind, 2);
        emon.Port.CellsSet(f, HSub, 5);
        if (mode == 1) {
            emon.Port.CellsSet(f, HCmap, 1);
            emon.Port.CellsSet(f, HTuStart, emon.Port.CellsLen(f));
            n = PfnCmap(f, data, 1);
            emon.Port.CellsSet(f, HTuN, n);
            emon.Port.CellsSet(f, HHastu, 1);
        }
        if (mode == 2) {
            emon.Port.CellsSet(f, HCmap, 2);
            emon.Port.CellsSet(f, HCidStart, emon.Port.CellsLen(f));
            n = PfnCmap(f, data, 2);
            emon.Port.CellsSet(f, HCidN, n);
        }
        if (emon.Port.CellsAt(f, HNcs) == 0) {
            PfnCsPut(f, 2, 0, 0, 0, 65535);
        }
        return n;
    }
    internal static int PfnStop(emon.Port.Src src) {
        // The status for a handle that is no font: need-bytes when the source
        // has missed (the handle may be 0 only because of the miss), else 1.
        if (Pdfsrc.PsMissed(src)) {
            return PfnNeedBytes();
        }
        return 1;
    }
    public static int PfnLoad(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells f, emon.Port.Cells @out, int fh0) {
        // Build the font whose dictionary is fh0 (a handle in `ar`, references
        // followed) into `f`, which this initializes. `out` is scratch for decoded
        // streams; `a` `b` `st` are the document layer's. Answers a `pfn-status`:
        // only a handle that is no dictionary fails (and `need-bytes` when the Src
        // missed, D075: then nothing built is kept); everything else is forgiven
        // and recorded in `(pfn-warn f)`.
        PfnInit(f);
        int fh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, fh0);
        int sub = 0;
        int sv = 0;
        if (fh == 0) {
            return PfnStop(src);
        }
        if (Pdflex.PlKindOf(ar, fh) != 7) {
            return PfnStop(src);
        }
        sv = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnSubtype());
        if (sv != 0) {
            if (Pdflex.PlNameIs(ar, sv, Pdfnames.PnType1()) == 1) {
                sub = 1;
            }
            if (Pdflex.PlNameIs(ar, sv, Pdfnames.PnMmType1()) == 1) {
                sub = 2;
            }
            if (Pdflex.PlNameIs(ar, sv, Pdfnames.PnTrueType()) == 1) {
                sub = 3;
            }
            if (Pdflex.PlNameIs(ar, sv, Pdfnames.PnType3()) == 1) {
                sub = 4;
            }
            if (Pdflex.PlNameIs(ar, sv, Pdfnames.PnType0()) == 1) {
                sub = 5;
            }
        }
        if (sub == 0) {
            sub = 1;
            if (Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnDescendantFonts()) != 0) {
                sub = 5;
            }
        }
        if (sub == 5) {
            PfnLoadComposite(src, ar, dc, a, b, st, f, @out, fh);
        } else {
            PfnLoadSimple(src, ar, dc, a, b, st, f, @out, fh, sub);
        }
        // CHECKPOINT (D075): a font read across a miss is not the font.
        if (Pdfsrc.PsMissed(src)) {
            return PfnNeedBytes();
        }
        return 0;
    }
}
